import AppKit
import WebKit
class Probe: NSObject, WKNavigationDelegate, WKScriptMessageHandler {
 var web:WKWebView!;var phases=0;var values:[String]=[]
 func webView(_ view:WKWebView,decidePolicyFor action:WKNavigationAction,decisionHandler:@escaping(WKNavigationActionPolicy)->Void){decisionHandler(["http","https"].contains(action.request.url?.scheme ?? "") ? .allow : .cancel)}
 func userContentController(_ controller:WKUserContentController,didReceive m:WKScriptMessage){guard let v=m.body as? String else{return};values.append(v);if v.hasPrefix("child:"){phases += 1;if phases==1{web.evaluateJavaScript("selectComparison('ios');document.querySelector('.design-panel').scrollTop=240;document.dispatchEvent(new Event('click'));",in:m.frameInfo,in:.page){_ in};DispatchQueue.main.asyncAfter(deadline:.now()+0.8){self.web.reload()}}else if phases==2{let data=try! JSONSerialization.data(withJSONObject:["values":values]);print(String(data:data,encoding:.utf8)!);exit(v=="child:ios:240" ? 0:2)}}}
}
let app=NSApplication.shared;app.setActivationPolicy(.prohibited);let p=Probe(),c=WKWebViewConfiguration();c.websiteDataStore = .nonPersistent();c.userContentController.add(p,name:"probe");c.userContentController.addUserScript(WKUserScript(source:"window.addEventListener('message',e=>{if(e.data?.opcbDesign===1&&e.data.type==='init')setTimeout(()=>window.webkit.messageHandlers.probe.postMessage('child:'+appState.compare+':'+document.querySelector('.design-panel').scrollTop),100)});",injectionTime:.atDocumentStart,forMainFrameOnly:false));let web=WKWebView(frame:NSRect(x:0,y:0,width:1200,height:900),configuration:c);p.web=web;web.navigationDelegate=p;let win=NSWindow(contentRect:web.frame,styleMask:[.borderless],backing:.buffered,defer:false);win.contentView=web;web.load(URLRequest(url:URL(string:CommandLine.arguments[1])!));DispatchQueue.main.asyncAfter(deadline:.now()+10){print("timeout \(p.values)");exit(3)};app.run()
